99	    const contextType: ContextType = 'http';
100	    const {
101	      argsLength,
102	      fnHandleResponse,
103	      isSseHandler,
104	      paramtypes,
105	      getParamsMetadata,
106	      httpStatusCode,
107	      responseHeaders,
108	      hasCustomHeaders,
109	      aggregateParamErrors,
110	    } = this.getMetadata(
111	      instance,
112	      callback,
113	      methodName,
114	      moduleKey,
115	      requestMethod,
116	      contextType,
117	    );
