379	  public isPipeable(type: number | string): boolean {
380	    return (
381	      type === RouteParamtypes.BODY ||
382	      type === RouteParamtypes.RAW_BODY ||
383	      type === RouteParamtypes.QUERY ||
384	      type === RouteParamtypes.PARAM ||
385	      type === RouteParamtypes.HEADERS ||
386	      type === RouteParamtypes.FILE ||
387	      type === RouteParamtypes.FILES ||
388	      isString(type)
389	    );
390	  }
391	
392	  public isParamErrorAggregated(type: number | string): boolean {
393	    return type === RouteParamtypes.PARAM || type === RouteParamtypes.QUERY;
394	  }
395	
396	  public createGuardsFn<TContext extends string = ContextType>(
397	    guards: CanActivate[],
398	    instance: Controller,
399	    callback: (...args: any[]) => any,
400	    contextType?: TContext,
401	  ): ((args: any[]) => Promise<void>) | null {
402	    const canActivateFn = async (args: any[]) => {
403	      const canActivate = await this.guardsConsumer.tryActivate<TContext>(
404	        guards,
405	        args,
406	        instance,
407	        callback,
408	        contextType,
409	      );
410	      if (!canActivate) {
411	        throw new ForbiddenException(FORBIDDEN_MESSAGE);
412	      }
413	    };
414	    return guards.length ? canActivateFn : null;
415	  }
416	
417	  public createPipesFn(
418	    pipes: PipeTransform[],
419	    paramsOptions: (ParamProperties & { metatype?: any })[],
420	    aggregateParamErrors = false,
421	  ) {
422	    const resolveParamValue = async <TRequest, TResponse>(
423	      param: ParamProperties & { metatype?: any },
424	      args: any[],
425	      req: TRequest,
426	      res: TResponse,
427	      next: Function,
428	    ) => {
429	      const {
430	        index,
431	        extractValue,
432	        type,
433	        data,
434	        metatype,
435	        pipes: paramPipes,
436	        schema,
437	      } = param;
438	      const value = extractValue(req, res, next);
439	
440	      args[index] = this.isPipeable(type)
441	        ? await this.getParamValue(
442	            value,
443	            { metatype, type, data, schema } as ArgumentMetadata,
444	            pipes.concat(paramPipes),
445	          )
446	        : value;
447	    };
448	
449	    const pipesFn = async <TRequest, TResponse>(
450	      args: any[],
451	      req: TRequest,
452	      res: TResponse,
453	      next: Function,
454	    ) => {
455	      if (!aggregateParamErrors) {
456	        await Promise.all(
457	          paramsOptions.map(param =>
458	            resolveParamValue(param, args, req, res, next),
459	          ),
460	        );
461	        return;
462	      }
463	
464	      // @Param()/@Query() pipes are executed serially, in parameter-index
465	      // order, and their rejections are collected and rethrown as a single
466	      // BadRequestException. Pipes bound to any other parameter keep the
467	      // existing fail-fast path (their errors propagate immediately).
468	      //
469	      // @Headers() parameters form an independent input domain: their pipes
470	      // always run and the transformed values are handed to the handler, but
471	      // a header pipe failure aborts the resolution immediately. The header
472	      // exception is never merged into the collected @Param()/@Query()
473	      // messages - any messages collected so far are discarded with this
474	      // request, so exception filters only observe the header exception.
475	      const orderedParams = [...paramsOptions].sort(
476	        (a, b) => a.index - b.index,
477	      );
478	      const messages: unknown[] = [];
479	      for (const param of orderedParams) {
480	        if (!this.isParamErrorAggregated(param.type)) {
481	          await resolveParamValue(param, args, req, res, next);
482	          continue;
483	        }
484	        try {
485	          await resolveParamValue(param, args, req, res, next);
486	        } catch (err) {
487	          // Only parameter validation errors are aggregated; any other
488	          // exception keeps the existing fail-fast path.
489	          if (!(err instanceof BadRequestException)) {
490	            throw err;
491	          }
492	          messages.push(...this.extractParamErrorMessages(err));
493	        }
494	      }
495	      if (messages.length > 0) {
496	        throw new BadRequestException(messages);
497	      }
498	    };
499	    return paramsOptions.length ? pipesFn : null;
500	  }
501	
502	  private extractParamErrorMessages(error: BadRequestException): unknown[] {
503	    const response = error.getResponse();
504	    if (typeof response === 'object' && response !== null) {
505	      const { message } = response as Record<string, unknown>;
506	      if (message !== undefined) {
507	        return Array.isArray(message) ? message : [message];
508	      }
509	    }
510	    return [response];
511	  }
512	
513	  public createHandleResponseFn(
514	    callback: (...args: unknown[]) => unknown,
515	    isResponseHandled: boolean,
516	    redirectResponse?: RedirectResponse,
517	    httpStatusCode?: number,
518	  ): HandleResponseFn {
519	    const renderTemplate = this.reflectRenderTemplate(callback);
520	    if (renderTemplate) {
521	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
522	        return await this.responseController.render(
523	          result,
524	          res,
525	          renderTemplate,
526	        );
527	      };
528	    }
529	    if (redirectResponse && isString(redirectResponse.url)) {
530	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
531	        await this.responseController.redirect(result, res, redirectResponse);
532	      };
533	    }
534	    const isSseHandler = !!this.reflectSse(callback);
535	    if (isSseHandler) {
536	      return async <
537	        TResult extends Observable<unknown> = any,
538	        TResponse extends HeaderStream = any,
539	        TRequest extends IncomingMessage = any,
540	      >(
541	        result: TResult,
542	        res: TResponse,
543	        req: TRequest,
544	      ) => {
545	        const rawResponse = (res as { raw?: TResponse }).raw ?? res;
546	        await this.responseController.sse(
547	          result,
548	          rawResponse,
549	          (req as any).raw || req,
550	          {
551	            additionalHeaders: res.getHeaders?.(),
552	            statusCode:
553	              (res as { statusCode?: number }).statusCode ??
554	              (rawResponse as { statusCode?: number }).statusCode,
555	          },
556	        );
557	      };
558	    }
559	    return async <TResult, TResponse>(result: TResult, res: TResponse) => {
560	      result = await this.responseController.transformToResult(result);
561	      !isResponseHandled &&
562	        (await this.responseController.apply(result, res, httpStatusCode));
563	      return res;
564	    };
565	  }
566	
567	  private isResponseHandled(
568	    instance: Controller,
569	    methodName: string,
570	    paramsMetadata: ParamProperties[],
571	  ): boolean {
572	    const hasResponseOrNextDecorator = paramsMetadata.some(
573	      ({ type }) =>
574	        type === RouteParamtypes.RESPONSE || type === RouteParamtypes.NEXT,
575	    );
576	    const isPassthroughEnabled = this.contextUtils.reflectPassthrough(
577	      instance,
578	      methodName,
579	    );
580	    return hasResponseOrNextDecorator && !isPassthroughEnabled;
581	  }
582	
583	  private attachSseAbortSignal<TRequest>(req: TRequest): void {
584	    const carrier = req as TRequest & {
585	      raw?: unknown;
586	      [SSE_ABORT_CONTROLLER]?: AbortController;
587	    };
588	    // Attach to both the framework request and its raw form (when present), since
589	    // @SseSignal() reads from the execution-context request while
590	    // RouterResponseController.sse() operates on the raw request.
591	    if (!carrier[SSE_ABORT_CONTROLLER]) {
592	      carrier[SSE_ABORT_CONTROLLER] = new AbortController();
593	    }
594	    if (carrier.raw && !(carrier.raw as object)[SSE_ABORT_CONTROLLER]) {
595	      (carrier.raw as object)[SSE_ABORT_CONTROLLER] =
596	        carrier[SSE_ABORT_CONTROLLER];
597	    }
598	  }
599	}
