33	/**
34	 * Sequences, failure boundaries and parallel-execution assertions shared
35	 * verbatim by the Express and Fastify adapters: both platforms must expose
36	 * exactly the same per-request isolation behaviour.
37	 */
38	export function registerIsolationSuite(deps: IsolationSuiteDeps): void {
39	  type SendRequest = (
40	    method: 'GET' | 'POST',
41	    path: string,
