45	  let close: () => Promise<void>;
46	
47	  beforeEach(async () => {
48	    const harness = await deps.createApp();
49	    request = harness.request;
50	    close = harness.close;
51	    resetIsolationState();
52	  });
53	
54	  afterEach(async () => {
55	    await close();
56	  });
57	
58	  describe(`[${deps.platformName}] per-request isolation`, () => {
59	    describe('sequential requests on an annotated route', () => {
60	      it('re-runs every pipe on a valid request after a double-error and calls the handler once with transformed values', async () => {
61	        const failed = await request('GET', '/p/abc?limit=x');
62	        expect(failed.status).toBe(400);
63	        expect(failed.body).toEqual({
64	          statusCode: 400,
65	          error: 'Bad Request',
66	          message: ['A', 'B'],
67	        });
68	        expect(isolationState.handlerCalls.aggregated ?? 0).toBe(0);
69	        expect(isolationState.pipeCalls).toEqual(['A', 'B']);
70	
71	        const ok = await request('GET', '/p/7?limit=10');
72	        expect(ok.status).toBe(200);
73	        expect(ok.text).toBe('7,10');
74	        // Both pipes of the second request ran again, in declaration order.
75	        expect(isolationState.pipeCalls).toEqual(['A', 'B', 'A', 'B']);
76	        expect(isolationState.handlerCalls.aggregated).toBe(1);
77	      });
78	
79	      it("reports only this request's messages on a double-error after a valid request (reverse order)", async () => {
80	        const ok = await request('GET', '/p/7?limit=10');
81	        expect(ok.status).toBe(200);
82	        expect(ok.text).toBe('7,10');
83	        expect(isolationState.handlerCalls.aggregated).toBe(1);
