        method: 'GET',
        url: '/p/other/missing?limit=x',
      });
      expect(response.statusCode).toBe(HttpStatus.NOT_FOUND);
      expect(response.json()).toEqual({
        statusCode: 404,
        error: 'Not Found',
        message: 'NOT-FOUND',
      });
